Let $w\in \operatorname{\mathfrak{S}}_{n}$.  Then the following are equivalent:
\begin{enumerate}
    \item The Schubert variety of $w$ is smooth.
    \item The permutation $w$ avoids patterns $3412$ and $4231$.
    \item The Bruhat interval $[e,w]$ is rank symmetric.
\end{enumerate}

\label{thm:smooth_enumeration}
For $n\geq 0$, let $a_n:=\#\{w\in \operatorname{\mathfrak{S}}_{n+1}\ |\ \text{$w$ avoids $3412$ and $4231$}\}$.  Then the generating function of the sequence $a_n$ is 
$$\sum_{n\geq 0} a_n\,x^n=\frac{1-5x+4x^2+x\sqrt{1-4x}}{1-6x+8x^2-4x^3}.$$

\label{thm:GG_polished}
Let $w\in \operatorname{\mathfrak{S}}_{n}$.  Then the following are equivalent:
\begin{enumerate}
\item The permutation $w$ is polished (i.e. $[e,w]$ is self-dual).
\item The permutation $w$ is smooth and avoids patterns $34521$, $54123$, $45321$, and $54312$.
\end{enumerate}

\label{thm:polished_GF}
Let $p_n:=\#\{w\in \operatorname{\mathfrak{S}}_{n+1}\ |\ \text{$w$ is polished}\}$.  Then
\begin{equation}\label{eqn:polished_GF}
\sum_{n\geq 0} p_n\,x^n=\frac{1-3x+x^2}{1-5x+5x^2-2x^3}.
\end{equation}

\label{thm:semi-polished_GF12}
Let $b_n:=\#\{w\in \operatorname{\mathfrak{S}}_{n+1}\ |\ w\text{ avoids $3412$, $4231$, $34521$,\text{ and } $54123$}\}$.  Then 
\begin{equation}\label{eqn:polished_type1_GF}
\sum_{n\geq 0}b_n\, x^n=\frac{1-5x+6x^2-4x^3}{1-6x+10x^2-8x^3+2x^4}.
\end{equation}
Let  $c_n:=\#\{w\in \operatorname{\mathfrak{S}}_{n+1}\ |\ w\text{ avoids $3412$, $4231$, $45321$,\text{ and } $54312$}\}$.  Then 
\begin{equation}\label{eqn:polished_type2_GF}
\sum_{n\geq 0}c_n\, x^n=\frac{1-4x+x^2}{1-5x+4x^2}.
\end{equation}

\label{lem:decomposable}
The permutation $w$ is decomposable in $\operatorname{\mathfrak{S}}_n$ if and only if there exists $1\leq i<n$ and a decomposition $w=w_1\cdot w_2$ such that $S(w_1)\subseteq [i-1]$ and $S(w_2)\subseteq [n-1]\setminus [i]$.

Furthermore, if $w=w_1\cdot w_2$ is decomposable in $\operatorname{\mathfrak{S}}_n$ as above, and $p$ is indecomposable in $\operatorname{\mathfrak{S}}_r$ for some $r\leq n$, then $w$ avoids $p$ if and only if $w_1$ and $w_2$ avoid $p$.

Suppose we have permutations $w_1$ and $w_2$ with $S(w_1)\subseteq [i]$ and $S(w_2)\subseteq [n-1]\setminus[i]$ for some $1 \leq i < n-1$.  Then for any $k\leq i$, we have
$w_1(k)\leq i+1$ and $w_2(k)=k,$ which implies that $w_1\cdot w_2(k)\leq i+1$.  This implies that $w_1\cdot w_2$ is left-weakly decomposable.  

Conversely, suppose that $w$ is left-weakly decomposable.  Then there exists $1\leq  i< n-1$ such that $w(k)\leq i+1$ for all $k\leq i$.  Define 
\[x=\min\{w(i+1),\ldots,w(n)\}\] and $j=w^{-1}(x)$.  Note that $x\leq i+1$ and $j\geq i+1$.  Define the permutations $w_1$ and $w_2$ by 
\begin{equation}\label{eqn:weak_facotorization}
w_1(k):=\begin{cases}
    w(k) & \text{if $k\leq i$}\\
    x & \text{if $k=i+1$}\\
    k & \text{if $k>i+1$}
\end{cases}\quad \text{and }\quad 
w_2(k):=\begin{cases}
    k & \text{if $k\leq i$}\\
    i+1& \text{if $k=j$}\\
    w(k) & \text{if $k> i+1$ and $k\neq j$}
\end{cases}
\end{equation}
Since $w_1(k)=k$ for all $k> i+1$ and we have $S(w_1)\subseteq [i]$.  Furthermore, since $w_2(k)=k$ for all $k\leq i$, we have $S(w_2)\subseteq [n]\setminus[i]$.  Finally, it is easy to verify that $w=w_1\cdot w_2$.  For uniqueness, we observe that $w=w_1\cdot w_2$ is a parabolic decomposition with respect to $S(w_2)$ and hence unique \cite[Proposition 2.4.4]{BB05}.  This completes the proof.

