\label{prop:staircase_permutation_properties}
Let $\mathcal{D}=\{B_1,\ldots, B_k\}$ be a staircase diagram on $[n-1]$ and let $\Lambda(\mathcal{D})=w(1)\cdots w(n)$.  Then the following are true:
\begin{enumerate}
    \item The support $\displaystyle S(\Lambda(\mathcal{D}))= S(\mathcal{D}):=\bigcup_{i=1}^k B_i$.
    \item If $B_i\prec B_{i+1}$ and $B_i=[r_i,l_i]$, then $w(l_i+1)<w(l_i+2)$.
    \item If $B_i\succ B_{i+1}$ and $B_{i+1}=[r_{i+1},l_{i+1}]$, then $w(r_{i+1}-1)<w(r_{i+1})$.
    \item If $\mathcal{D}^*$ is the dual staircase diagram to $\mathcal{D}$, then $\Lambda(\mathcal{D})^{-1}=\Lambda(\mathcal{D}^*)$.
\end{enumerate}

\label{prop:staircase_wk_decomp}
    Let $k\geq 2$, $\mathcal{D}=\{B_1,\ldots, B_k\}$, and suppose $B_i\cap B_{i+1}=\varnothing$ for some $i<k$. Define the subdiagrams $$\mathcal{D}_1:=\{B_1,\ldots,B_i\}\quad\text{and}\quad \mathcal{D}_2:=\{B_{i+1},\ldots, B_k\}.$$  of $\mathcal{D}$. Then the following are true:
    \begin{enumerate}

        \item If $B_i\prec B_{i+1}$, then $\Lambda(\mathcal{D})=\Lambda(\mathcal{D}_2)\cdot \Lambda(\mathcal{D}_1)$.
        \item If $B_i\succ B_{i+1}$, then $\Lambda(\mathcal{D})=\Lambda(\mathcal{D}_1)\cdot \Lambda(\mathcal{D}_2)$.
        \item If $B_i\cup B_{i+1}$ is disconnected, then $\Lambda(\mathcal{D})=\Lambda(\mathcal{D}_1)\cdot \Lambda(\mathcal{D}_2)=\Lambda(\mathcal{D}_2)\cdot \Lambda(\mathcal{D}_1)$.
    \end{enumerate}
Furthermore, the products in parts (1) and (2) are weakly decomposing factorizations and the product in part (3) is a decomposing factorization.

