Since $\mathcal{D}$ avoids $Q$ if and only if each component avoids $Q$, we have the recursion:
\[z'_n=\sum_{k=1}^{n} \bar z_{k}\cdot 2z'_{n-k}.\]
Thus 
\begin{equation}\label{eqn:Z_bar_2_Z_prime}
Z'_Q(x)=\overline{Z}_Q(x)+2\overline{Z}_Q(x)\cdot Z'_Q(x)\quad \text{giving}\quad Z'_Q(x)=\frac{\overline{Z}_Q(x)}{1-2\overline{Z}_Q(x)}.
\end{equation}
Furthermore, any staircase diagram is a disjoint union of fully supported staircase diagrams.  Since a strongly indecomposable permutation is also indecomposable, \Cref{lem:decomposable} implies 
\begin{equation}\label{eqn:Z_prime_2_Z}
Z_Q(x)=\frac{1+Z'(x)}{1-x-xZ'_Q(x)}.
\end{equation}
Combining \Cref{eqn:Z_bar_2_Z_prime} and \Cref{eqn:Z_prime_2_Z} completes the proof.

\label{def:chain-indecomposable}
 We say a permutation $p$ is \textbf{chain indecomposable} if the following hold:
 \begin{enumerate}
 \item For any staircase diagram $\mathcal{D}$, if $\Lambda(\mathcal{D})$ contains $p$, then there exists a strongly connected chain $\mathcal{D}'\subseteq \mathcal{D}$ such that $\Lambda(\mathcal{D}')$ contains $p$. 
 \item For any strongly connected chain $\mathcal{D}$, if $\Lambda(\mathcal{D})$ avoids $p$, then $\mathcal{B}r(\mathcal{D})$ avoids $p$.
 \end{enumerate}

\label{thm:connected2chains_gf}
    Let $Q$ be an inverse invariant set of chain indecomposable permutations.  Then 
    \[\overline{Z}_Q(x)=\frac{xZ^+_Q(x)}{2x-(1-x)Z^{+}_Q(x)}.\]

\label{cor:GF_summary}
    Let $Q$ be a set of permutation patterns and let $Z_Q(x)$ denote the generating function for the number of staircase diagrams on $[n]$ that avoid $Q$ (or equivalently, smooth permutations in $\operatorname{\mathfrak{S}}_{n+1}$ that avoid $Q$).
    \begin{enumerate}
    \item If $Q$ is a strongly indecomposable set, then $Z_Q(x)$ is determined by $\overline{Z}_Q(x)$, the generating function for the number of strongly connected staircase diagrams that avoid $Q$.  Furthermore, $Z_Q(x)$ is rational if and only if $\overline{Z}_Q(x)$ is rational.

    \item If $Q$ is an inverse invariant and chain indecomposable set, then $Z_Q(x)$ is determined by $Z^+_Q(x)$, the generating function for the number of strongly connected, increasing chains that avoid $Q$.  Furthermore, $Z_Q(x)$ is rational if and only if $Z^+_Q(x)$ is rational.
    \end{enumerate}

